	.include "rmt.s"

; 3d00		a=note0-63,x=trackindex0-7,y=instrument0-63
	ORG	$3d00
	sta	trackn_note,x	; Sets trackn_note
.if FEAT_BASS16
	sta	trackn_outnote,x	; (if nothing changes it anymore, it stays the same as note)
.endif
	tya
	asl	a
	sta	trackn_instrx2,x
	bmi	usi1	; If the instrument number *2 is >127 => the instrument setup is skipped (for compatibility with the routine)
	tay
	jmp	SetUpInstrumentY2	; Y holds the instrument number *2, X the track number
							; jsr-rts
usi1 = *
	rts

	ORG	xata_rtshere	; Patches the RMT routine's code so SetUpInstrumentY2 can be called as a subroutine
	rts


; 3e00		a=volume0-15,x=trackindex0-7
	ORG	$3e00
	asl	a
	asl	a
	asl	a
	asl	a
	sta	trackn_volume,x	; Sets the volume
	rts

; 3e80		x=trackindex0-7
	ORG	$3e80
	lda	#0
	sta	trackn_volume,x	; Zeroes the volume
	sta	trackn_instrhb,x	; Zeroes the instrument's HB => turns the instrument processing off
	sta	trackn_instrdb,x	; Zeroes the DB too (extra, just so it does not stay nonzero; not required)
	sta	trackn_audc,x	; Silences the respective sound generator
	rts

